const event = $json || {};
const execution = event.execution || {};
const trigger = event.trigger || {};
const workflow = event.workflow || {};
const error = execution.error || trigger.error || trigger.error?.cause || {};
const digits = value => String(value || '').replace(/[^0-9]/g,'');
const admin = digits($env.PLUTO_ERROR_ADMIN_PHONE || $env.PLUTO_MANAGER_CHAT_ID || '');
const session = String($env.PLUTO_GOWA_SESSION_ID || '').trim();
const clean = value => String(value || 'non disponible')
  .replace(/sk-[A-Za-z0-9_-]{12,}/g,'[CLE_OPENAI_MASQUEE]')
  .replace(/(Bearer\s+)[A-Za-z0-9._-]+/gi,'$1[MASQUE]')
  .replace(/((?:password|token|api[_ -]?key)\s*[:=]\s*)[^\s,;]+/gi,'$1[MASQUE]');
const message = clean(error.message || error.cause?.message || trigger.error?.message);
const stack = clean(error.stack || error.cause?.stack || trigger.error?.cause?.stack).slice(0,1400);
const lastNode = clean(execution.lastNodeExecuted || trigger.error?.node?.name);
const executionId = clean(execution.id);
const fingerprint = [workflow.id,workflow.name,lastNode,message].join('|').slice(0,500);
const state = $getWorkflowStaticData('global');
state.recent = state.recent || {};
const now = Date.now();
for (const [key,value] of Object.entries(state.recent)) if (now-Number(value)>30*60*1000) delete state.recent[key];
let hash = 0; for (const ch of fingerprint) hash = ((hash<<5)-hash+ch.charCodeAt(0))|0;
const dedupKey = String(hash);
const duplicate = Boolean(state.recent[dedupKey] && now-state.recent[dedupKey] < 5*60*1000);
if (!duplicate) state.recent[dedupKey] = now;
const lines = [
  '🚨 *PLUTO — ERREUR D’EXÉCUTION*',
  '', `Heure : ${new Date().toISOString()}`,
  `Workflow : ${clean(workflow.name)} (${clean(workflow.id)})`,
  `Exécution : ${executionId}`, `Mode : ${clean(execution.mode || trigger.mode)}`,
  `Dernier nœud : ${lastNode}`, `Erreur : ${message}`,
  execution.retryOf ? `Nouvelle tentative de : ${clean(execution.retryOf)}` : '',
  execution.url ? `Diagnostic n8n : ${clean(execution.url)}` : '',
  '', '*Trace technique sécurisée*', stack,
  '', 'Action recommandée : ouvrir l’exécution, corriger la cause puis utiliser Retry with current workflow.'
].filter(Boolean);
return [{json:{
  configured:Boolean(admin && session),duplicate,chat_id:admin,session_id:session,
  message:lines.join('\n').slice(0,3900),workflow_name:workflow.name,execution_id:execution.id
}}];
